<div class="page-actions"><p class="muted">Catat pemasukan dan pengeluaran usaha dalam satu buku kas.</p><a class="btn btn-primary" href="<?= site_url('finance/new') ?>">＋ Catat transaksi</a></div>
<form method="get" action="<?= site_url('finance') ?>" class="filter-bar"><label>Bulan laporan<input type="month" name="month" value="<?= esc($month) ?>"></label><button class="btn btn-plain">Tampilkan</button></form>
<div class="summary-grid"><div class="summary-card"><span>Pemasukan</span><strong class="positive">Rp <?= number_format($summary['masuk'], 0, ',', '.') ?></strong></div><div class="summary-card"><span>Pengeluaran</span><strong class="negative">Rp <?= number_format($summary['keluar'], 0, ',', '.') ?></strong></div><div class="summary-card"><span>Saldo bersih</span><strong>Rp <?= number_format($summary['masuk'] - $summary['keluar'], 0, ',', '.') ?></strong></div></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>JENIS / KATEGORI</th><th>KETERANGAN</th><th>PESANAN</th><th>NOMINAL</th><th></th></tr></thead><tbody><?php foreach ($entries as $entry): ?><tr><td><?= esc(date('d/m/Y', strtotime($entry['entry_date']))) ?></td><td><span class="badge <?= $entry['type'] === 'masuk' ? 'badge-income' : 'badge-expense' ?>"><?= esc(ucfirst($entry['type'])) ?></span><small class="table-sub"><?= esc($entry['category']) ?></small></td><td><?= esc($entry['description']) ?></td><td><?= esc($entry['booking_code'] ?? '—') ?></td><td class="<?= $entry['type'] === 'masuk' ? 'positive' : 'negative' ?>">Rp <?= number_format((float) $entry['amount'], 0, ',', '.') ?></td><td><?php if ($entry['booking_id'] === null): ?><form method="post" action="<?= site_url('finance/' . $entry['id'] . '/delete') ?>" onsubmit="return confirm('Hapus transaksi ini?')"><?= csrf_field() ?><button class="link-danger">Hapus</button></form><?php else: ?><span class="muted">Otomatis</span><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php if (! $entries): ?><div class="empty-state">Belum ada transaksi untuk bulan ini.</div><?php endif ?></div>
